import {performance} from 'node:perf_hooks';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';
import {baseline} from './builders.mjs';
import {buildProductSelection} from '../../../lib/credit-engine/product-selection/engine.ts';
import {validateProductInput} from '../../../lib/credit-engine/product-selection/validation.ts';
import {extractProductCase} from '../../../lib/credit-engine/product-selection/case.ts';
import {evaluateProduct} from '../../../lib/credit-engine/product-selection/evaluator.ts';
import {productCapacity} from '../../../lib/credit-engine/product-selection/capacity.ts';
import {existingProductExposure} from '../../../lib/credit-engine/product-selection/portfolio.ts';
import {rankProducts} from '../../../lib/credit-engine/product-selection/ranking.ts';
import {PRODUCT_SELECTION_POLICY as p} from '../../../lib/credit-engine/product-selection/policy.ts';
import {PRODUCT_FAMILY_REGISTRY as registry} from '../../../lib/credit-engine/product-selection/registry.ts';
import {expectations,compareProducts} from './lab.mjs';
import {id,canonical} from '../../../lib/credit-engine/product-selection/common.ts';
export function benchmark(){const x=baseline(),r=buildProductSelection(x),candidate=registry.products[0],cs=registry.products.map(d=>evaluateProduct(x,d,p)),out=[];
 const measure=(phase,iterations,fn)=>{const start=performance.now();for(let i=0;i<iterations;i++)fn();out.push({phase,iterations,totalMs:Math.round((performance.now()-start)*100)/100});};
 measure('validation',1000,()=>validateProductInput(x));measure('caseExtraction',1000,()=>extractProductCase(x));measure('registryEvaluation',1000,()=>registry.products.map(d=>evaluateProduct(x,d,p)));measure('capacityAlignment',1000,()=>productCapacity(x,candidate));measure('portfolioExposure',1000,()=>existingProductExposure(x,candidate.productFamily));measure('candidateRanking',1000,()=>rankProducts(cs,'WORKING_CAPITAL','ASSESSED',p,registry));
 measure('finalizationFingerprintProjection',1000,()=>Object.fromEntries(Object.entries(x).map(([k,v])=>[k,id('product-upstream',canonical(v))])));
 measure('productSelection1000',1000,()=>buildProductSelection(x));measure('sourceCanonicalPipeline200',200,()=>buildProductSelection(baseline()));measure('registryRanking1000',1000,()=>rankProducts(registry.products.map(d=>evaluateProduct(x,d,p)),'WORKING_CAPITAL','ASSESSED',p,registry));measure('goldenExpectations1000',1000,()=>expectations({input:x,expected:{status:'ASSESSED',primaryCandidateProducts:['REVOLVING_CREDIT_LINE','CREDIT_LINE','OVERDRAFT']}},r));measure('pairwiseComparisons1000',1000,()=>compareProducts(r,r));return out;
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))console.log(JSON.stringify(benchmark(),null,2));
